//! Differential fuzzing of `integration::js` against node itself (plan 011).
//!
//! `fixtures/js_semantics.json` holds node's answers for a seeded corpus of
//! 5,000 strings, generated by scripts/upstream-oracle/gen-js_semantics.ts:
//! `String(Number(x))`, `decodeURI(x)` and the value Express 5's query parser
//! reads from `k=x`. Upstream reads URL strings with exactly these, so where
//! they disagree with ours, the same request means different things.

use ontime_core::integration::js;
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct NumberAnswer {
    string: String,
    negative_zero: bool,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    text: String,
    number: NumberAnswer,
    #[serde(rename = "decodeURI")]
    decode_uri: Option<String>,
    query: Option<String>,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

fn cases() -> Vec<Case> {
    let fixture: Fixture =
        serde_json::from_str(include_str!("fixtures/js_semantics.json")).unwrap();
    fixture.cases
}

fn report(what: &str, failures: &[String], total: usize) {
    assert!(
        failures.is_empty(),
        "{what}: {} of {total} differ from node:\n{}",
        failures.len(),
        failures
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn number_matches_node() {
    let cases = cases();
    let mut failures = Vec::new();
    for case in &cases {
        let ours = js::number(&Value::String(case.text.clone()));
        let shown = js::number_to_string(ours.unwrap_or(f64::NAN));
        let negative_zero = ours.is_some_and(|n| n == 0.0 && n.is_sign_negative());
        if shown != case.number.string || negative_zero != case.number.negative_zero {
            failures.push(format!(
                "Number({:?}): node {} (-0: {}), ours {shown} (-0: {negative_zero})",
                case.text, case.number.string, case.number.negative_zero
            ));
        }
    }
    report("Number()", &failures, cases.len());
}

#[test]
fn decode_uri_matches_node() {
    let cases = cases();
    let mut failures = Vec::new();
    for case in &cases {
        let ours = js::decode_uri(&case.text).ok();
        if ours != case.decode_uri {
            failures.push(format!(
                "decodeURI({:?}): node {:?}, ours {ours:?}",
                case.text, case.decode_uri
            ));
        }
    }
    report("decodeURI()", &failures, cases.len());
}

#[test]
fn query_values_match_express() {
    let cases = cases();
    let mut failures = Vec::new();
    for case in &cases {
        let Some(want) = &case.query else { continue };
        let ours = js::decode_query_component(&case.text);
        if ours != *want {
            failures.push(format!("k={:?}: node {want:?}, ours {ours:?}", case.text));
        }
    }
    report("query", &failures, cases.len());
}
